for (const item of $input.all()) {
  const status = String(item.json.Status || '').trim().toLowerCase();
  const videoPath = String(item.json.Video_Path || '').trim();
  const caption = String(item.json.Caption || '').trim();
  const draftUrl = String(item.json.Draft_Video_URL || '').trim();
  const publishId = String(item.json.TikTok_Publish_ID || '').trim();

  if (status === 'draft' && videoPath && caption && !draftUrl) {
    return [{
      json: {
        action: 'create_review',
        ID: item.json.ID,
        Video_Path: item.json.Video_Path,
        Caption: item.json.Caption,
      },
    }];
  }

  if (status === 'approved' && videoPath && caption && !publishId) {
    return [{
      json: {
        action: 'publish',
        ID: item.json.ID,
        Video_Path: item.json.Video_Path,
        Caption: item.json.Caption,
      },
    }];
  }
}

return [{ json: { action: 'idle', Note: 'Phase 4: no eligible row found' } }];

const item = $input.first().json;
const videoPath = String(item.Video_Path || '').trim();
const baseName = videoPath.split(/[\\/]/).pop() || 'final.mp4';
const readFilePath = videoPath.replace(/^\/workspace\/runtime\//, '/home/node/.n8n-files/runtime/');
return [{
  json: {
    ...item,
    Drive_File_Name: 'phase4_draft_' + item.ID + '_' + baseName,
    Read_File_Path: readFilePath,
  },
}];

const upload = $('Upload Draft Video To Drive').item.json;
const source = $('Prepare Drive Draft Metadata').item.json;
const fileId = String(upload.id || upload.fileId || '').trim();
if (!fileId) {
  throw new Error('Google Drive upload did not return a file id');
}
const draftUrl = String(upload.webViewLink || '').trim() || ('https://drive.google.com/file/d/' + fileId + '/view');

return [{
  json: {
    ID: source.ID,
    Video_Path: source.Video_Path,
    Caption: source.Caption,
    Draft_Video_URL: draftUrl,
    Draft_Drive_File_ID: fileId,
    Status: 'Draft',
    Note: 'Phase 4: draft uploaded to Drive and sent to Telegram for review',
  },
}];

const decision = $('Save Admin Decision + Ack Telegram').item.json;
const approvedId = String(decision.id || '').trim();
if (!approvedId) {
  throw new Error('Approved callback did not return a row ID');
}

for (const item of $input.all()) {
  const id = String(item.json.ID || '').trim();
  const status = String(item.json.Status || '').trim().toLowerCase();
  const videoPath = String(item.json.Video_Path || '').trim();
  const caption = String(item.json.Caption || '').trim();
  const publishId = String(item.json.TikTok_Publish_ID || '').trim();
  if (id !== approvedId) continue;
  if (status !== 'approved') continue;
  if (!videoPath || !caption || publishId) continue;

  return [{
    json: {
      ID: item.json.ID,
      Video_Path: item.json.Video_Path,
      Caption: item.json.Caption,
    },
  }];
}

return [{ json: { ID: approvedId, Status: 'Publish Failed', Note: 'Phase 4: approved row was not publishable after callback' } }];
